{
  "title": "山村谜语",
  "scene": "你来到了一个古老的山村，村里的老人们都在讨论一个古老的谜语。他们说，解开这个谜语的人可以得到村长的宝藏。你找到了村长，他给你看了三个盒子，分别写着‘木’、‘水’、‘山’。村长说，宝藏在盒子里，但只有选择正确盒子的人才能得到。旁边的小孩偷偷告诉你，村长最喜欢的是自然和和平。",
  "goal": "找到村长的宝藏",
  "clue": "小孩的暗示‘自然和和平’对应‘水’，因为水象征着生命和和平。",
  "choices": [
    {
      "id": "A",
      "text": "选择‘木’的盒子",
      "outcome": "你打开了‘木’的盒子，里面什么也没有。村长摇摇头说，木头虽然也是自然的一部分，但它不是最能代表自然和和平的。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "选择‘水’的盒子",
      "outcome": "你打开了‘水’的盒子，里面装着一张古老的地图和一些金币！村长笑着夸奖你，说你很聪明，水确实是最能代表自然和和平的。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "选择‘山’的盒子",
      "outcome": "你打开了‘山’的盒子，里面有一封信，信上写着‘自然和和平’的谜底是‘水’。村长叹了口气，说你差点就对了，但下次记得仔细听线索。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
